function legalReason(card,key,asCounter=false){const s=side(key);if(s.superKey==='brock'&&/Amazing Entrance/i.test(card.name||''))return 'Brock Lesnar may not play Amazing Entrance.';const verified=verifiedSpecialLegal(card,key,asCounter);if(verified!==null&&verified)return verified;if(state.busy&&!asCounter)return'Action resolving.';if(state.control!==key&&!asCounter&&!/^(Boring|BreakEX2)\.gac$/i.test(String(card.sourceFile||'')))return'No match control.';if(state.hold)return'A submission is active.';if(s.stun>0)return`${s.name} is stunned.`;if(/^SuperMomentum(?:LE)?\.gac$/i.test(String(card.sourceFile||''))&&s.superKey!=='hurricane')return'Hurricane Trademark only.';if(card.cardClass==='Momentum'){const gains=card.momentumChanges?.gain||{[card.momentumType]:card.momentumAmount||1};const useful=Object.entries(gains).some(([t,n])=>Number(n)>0&&momentumGainRoom(key,t)>0);if(!useful)return'Original Superstar momentum maximum reached.';}if(card.cardClass==='Momentum'&&s.momentumPlayedSinceSuccess)return'You must connect with a move before playing another Momentum page.';if(s.momentumPlayedSinceSuccess&&!asCounter&&!['Move','Trademark'].includes(card.cardClass))return'After playing Momentum, your next page must be a move attempt.';const cost=actualCost(card,key);if(cost>totalMomentum(s))return`Needs ${cost} total momentum (you have ${totalMomentum(s)}).`;if(card.minTurn&&state.round<card.minTurn)return`Playable after turn ${card.minTurn-1}.`;if(card.workingStiff&&s.inPlay.some(e=>e.workingStiff))return'Only one Working Stiff may be in play.';if(card.supportPage&&s.inPlay.some(e=>e.supportPage))return'Only one Support page may be in play.';const mods=String(card.modifiers||'').toLowerCase();if(mods.includes('event')){if(s.eventNamesPlayed.includes(card.name))return'Each Event may only be played once per match.';if(s.eventsPlayed>=3)return'Only three Event pages may be played per match.';}if(mods.includes('referee')&&['player','cpu'].some(x=>side(x).inPlay.some(e=>String(e.modifiers||e.card?.modifiers||'').toLowerCase().includes('referee'))))return'Only one Referee Special may be in play.';if(card.onlyOneInPlay&&s.inPlay.some(e=>e.sourceFile===card.sourceFile||e.name===card.name))return`Only one ${card.name} may be in play.`;if(card.requiresInPlay){const needle=card.requiresInPlay.toLowerCase();const present=[...s.inPlay,...side(other(key)).inPlay].some(e=>String(e.name||'').toLowerCase().includes(needle));if(!present)return`Requires ${card.requiresInPlay} in play.`;}if(card.gotAllOfIt&&!s.hand.some(x=>x.cardClass==='Move'&&!String(x.modifiers||'').toLowerCase().includes('defensive')))return'Got All Of It! must be played with a non-defensive move.';if(card.latinoHeat&&((s.momentum.Knowledge||0)>0||s.latinoHeatUses>=3))return (s.momentum.Knowledge||0)>0?'Latino Heat requires no Knowledge Momentum.':'Latino Heat may only be played three times per match.';if(card.callingForIt&&s.hitStreak<3)return'Needs three connected moves in a row.';if(s.pendingCallingForIt&&card.cardClass==='Move'&&s.connectedMoves.includes(card.name))return"He's Calling For It requires a move not yet connected this match.";for(const [type,need] of Object.entries(card.momentumRequirements||{})){if((s.momentum[type]||0)<need)return`Needs ${need} ${type} momentum.`;}if(card.counterOnly&&!asCounter)return'Counter only.';if(other&&false){}if((/Plead to the Referee|Good Officiating/i.test(card.name))&&side(other(key)).superKey==='christian'&&(side(other(key)).warnings||0)===0)return`Christian has no Warnings.`;if(card.face&&s.alignment==='Heel')return'Face page conflicts with Heel.';if(card.heel&&s.alignment==='Face')return'Heel page conflicts with Face.';if(card.requirement&&!s.methods[card.requirement])return`Needs ${card.requirement}.`;if(!asCounter){const txt=String(card.description||'').toLowerCase();if((txt.includes('only if your opponent is on the mat')||txt.includes('only if opponent is on the mat'))&&!['Grounded','Prone','Victim Below'].includes(state.position))return'Opponent must be on the mat.';if(txt.includes('only if your opponent is standing')&&state.position!=='Standing')return'Opponent must be standing.';}return''}
const isLegal=(c,k)=>!legalReason(c,k);
function removeCard(k,c){const s=side(k),i=s.hand.findIndex(x=>x.instance===c.instance);if(i>=0)s.hand.splice(i,1);s.discard.push(c)}
function addLog(t){state.log.unshift(t);state.log=state.log.slice(0,50)}
function findCounter(k,attack){if(attack.uncounterable)return null;const s=side(k),positions=[attack.position,attack.originalMoveType,attack.setsPosition].filter(Boolean).map(x=>String(x).toLowerCase());const options=s.hand.filter(c=>c.cardClass!=='Gameplan'&&!legalReason(c,k,true)&&c.counters?.some(x=>positions.includes(String(x).toLowerCase())));return options.sort((a,b)=>(b.damage+b.momentumGain)-(a.damage+a.momentumGain))[0]||null}
